from pathlib import Path
import hashlib,json,subprocess,shutil,importlib.util
R=Path.cwd();D=R/'polarity-repair';D.mkdir(exist_ok=False)
def put(p,t):p.parent.mkdir(parents=True,exist_ok=True);p.open('x',encoding='utf-8',newline='\n').write(t)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
mutable=['rebuild/tools/validate_packet.py','tools/verify_submission.py','README.md','results.md','SUBMISSION_COMMENT.md','packaging/COMPLIANCE.md','rebuild/README.md']
files=[n for n in subprocess.check_output(['git','ls-files','-z']).decode().split('\0') if n]
for n in mutable:p=D/'before'/n;p.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(R/n,p)
art={str(p.relative_to(R)).replace('\\','/'):sha(p) for f in ['','final-repair','final-repair-verified','release','warning-release','warning-release-verified','scope-release','scope-guard-release'] for p in (R/'dist'/f).glob('*') if p.is_file()}
put(D/'preservation.json',json.dumps({'commit':subprocess.check_output(['git','rev-parse','HEAD']).decode().strip(),'tracked':{n:sha(R/n) for n in files},'mutable':mutable,'artifacts':art},indent=2))
shutil.copytree(R/'red-team-guard/fixtures',D/'fixtures');ex=json.loads((R/'red-team-guard/expectations.json').read_text())
rows=[('Unrelated personal correspondence','Private calendar: unrelated personal correspondence:'),('Unrelated personal correspondence','Participation does not depend on attendance at these family events.'),('Unrelated personal correspondence','My birthday dinner is December 1, 2027 at 7 PM.'),('Official participation instructions','Only those who attend these events may take part.'),('Official participation instructions','Our farewell dinner is December 2, 2027 at 7 PM.'),('Unrelated personal correspondence','Private correspondence:'),('Unrelated personal correspondence','Our retirement lunch and family reunion are December 3, 2027 at 2 PM.'),('Official receipt instructions','My birthday dinner is December 4, 2027 at 7 PM and lodge the sealed participation credential by December 5, 2027 at 2 PM.')]
p=D/'fixtures/D-polarity-and-coordination.md';put(p,''.join(f'S{i:03} | {a} | {b}\n' for i,(a,b) in enumerate(rows,1)));ex[p.stem]={'source_sha256':sha(p),'required':{'S005':[6],'S008':[6]},'forbidden':{'S005':[12],'S008':[12]},'exclusive':{f'S{i:03}':[12] for i in [1,2,3,6,7]}}
put(D/'expectations.json',json.dumps(ex,indent=2));shutil.copyfile(R/'scope-guard-repair/full-expectations.json',D/'full-expectations.json')
cs=[]
for folder,file,prefix in [('scope-guard-repair','control-definitions-release.json','prior-'),('red-team-guard','control-definitions.json','red-')]:
 for c in json.loads((R/folder/file).read_text(encoding='utf-8')):c['name']=prefix+c['name'];cs.append(c)
s=importlib.util.spec_from_file_location('v',R/'rebuild/tools/validate_packet.py');v=importlib.util.module_from_spec(s);s.loader.exec_module(v)
def card(bs):
 ls=[v.TITLE]
 for n,h in enumerate(v.HEADINGS,1):ls.append(h);ls.extend([f'- “{b}” [source: source-packet.md:S{i:03}; Document p. {i}]' for i,b in enumerate(bs,1)] if n==12 else ['- not in source'])
 return '\n'.join(ls)+'\n'
extras=[('not-only-positive',['Participation not only depends on attendance at these events but also on completion of the assessment.','Our farewell dinner is December 2, 2027 at 7 PM.'],True,'S002'),('negative-without-owner',[rows[0][1],rows[1][1],rows[2][1]],False,'S003'),('private-duty-and-private-event',['I have to attend my daughter’s birthday dinner on December 1, 2027 at 7 PM and my graduation ceremony is December 2, 2027 at 2 PM.'],False,'S001'),('private-bare-coordinated-activities',[rows[6][1]],False,'S001'),('private-event-and-contribution',['My birthday dinner is December 1, 2027 at 7 PM and bring $5 for dinner.'],False,'S001'),('unknown-action-after-and',[rows[7][1]],True,'S001'),('private-cued-official-second-clause',['My birthday dinner is December 1, 2027 at 7 PM and our family reunion costs an official participation deposit by December 2, 2027 at 2 PM.'],True,'S001'),('exclusion-of-other-heading',['Companies must attend all events, including the subsection titled Private events; the subsection titled Private correspondence is excluded from these activities.','Private events:','Our farewell dinner is December 2, 2027 at 7 PM.'],True,'S003'),('latest-exclusion',['Companies must attend all events, including the subsection titled Private correspondence:','The subsection titled Private correspondence is excluded from these activities.','Private correspondence:','My birthday dinner is December 1, 2027 at 7 PM.'],False,'S004'),('latest-inclusion',['Companies must attend all events; the subsection titled Private correspondence is excluded from these activities.','These mandatory events now include the subsection titled Private correspondence.','Private correspondence:','Our farewell dinner is December 2, 2027 at 7 PM.'],True,'S004'),('annotated-clinical',['Private calendar — clinical visits for patients:','Our farewell dinner is December 2, 2027 at 7 PM.'],True,'S002'),('annotated-private-colon',[rows[0][1],rows[2][1]],False,'S002')]
for n,bs,w,sid in extras:cs.append({'name':n,'source':''.join(f'S{i:03} | Document p. {i} | {b}\n' for i,b in enumerate(bs,1)),'card':card(bs),'valid':True,'warning':w,'sid':sid})
put(D/'control-definitions.json',json.dumps(cs,ensure_ascii=False,indent=2))
for n in ['run_arm.py','controls.py','score_core.py','score_core_strict.py','score_full.py','score_models.py','verify.py','package.py','verify_delivery.py']:
 put(D/n,(R/'scope-guard-repair'/n).read_text().replace('scope-guard-repair','polarity-repair').replace('scope-guard-release','polarity-release').replace('guard-release-clone','polarity-release-clone'))
put(D/'replay_controls.py',(R/'scope-guard-repair/replay_controls.py').read_text().replace('scope-guard-repair','polarity-repair').replace('historical-control-replays-v2','historical-control-replays'))
put(D/'submission-plan.json',json.dumps({'sentences':['I rebuilt my Comp #13 Translator entry, RFP-COMPASS: [PUBLIC_REPOSITORY_URL].','The feedback line that drove it was: “A noisy-input test in `run-results/` showing a stapled thread held in Section 12 only.”','The repository preserves frozen questions, paired raw runs, failed repairs, ties and regressions, and the tested limits of the warning logic.'],'required_count':3},ensure_ascii=False,indent=2))
put(D/'PROTOCOL.md','''# Polarity and clause repair frozen protocol - 2026-10-24
Preserve all prior tracked bytes and 41 sealed delivery files; snapshot seven mutable documents. Freeze 116 controls, prior red-team A/B/C plus new D and source-hash-bound expectations, and unchanged full-RFP matrix before execution. Keep root frozen questions unchanged. Original runs core A-E, supplemental A-D, full 221-statement RFP first; commit complete raw baseline before candidate mutation. Commit warning-only candidate before rebuilt calls. Same canonical runners, gpt-6-astra medium, six unchanged knowledge files, ordered fixtures, fresh sessions and exact full-RFP continues. No tools, retries, best-of selection, corrected raw outputs or evaluator answers in model inputs. Def difference onward must remain byte-identical. Repair generic event-scope recognition, mixed conjunction boundaries, dependency polarity, local inclusion/exclusion and annotated private headings together. Guards cover positive/negative dependencies, private coordinated activities, official mixed clauses, local/latest subsection relations and clinical content. Preserve intermediate failures; report ties, regressions and finite-heuristic limits. No publication.
''');print(len(files),len(art),len(cs))
